use crate::policy::*;
use crate::vault::*;
use crate::{Error, Result};
use std::cell::RefCell;
use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::rc::Rc;
use std::sync::atomic::{AtomicUsize, Ordering};
fn synthetic_base() -> &'static Path { if cfg!(target_os = "windows") { Path::new(r"C:\synthetic") } else { Path::new("/synthetic") } }
const OWNER_A:&str="11111111-1111-4111-8111-111111111111";
const OWNER_B:&str="22222222-2222-4222-8222-222222222222";
const DEVICE_A:&str="aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
const DEVICE_B:&str="bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb";
fn target(env:CloudEnv)->CloudTarget { CloudTarget::new(env,match env {CloudEnv::Development=>"vsphftnmfzfoufasjttd",CloudEnv::Production=>"hutqsfftioxtredcjhsy"}).unwrap() }
fn scope(env:CloudEnv,owner:&str,device:&str)->AccountScope {AccountScope::new(target(env),owner,device).unwrap()}
#[derive(Default)]
struct State { data:HashMap<CredentialKey,Vec<u8>>, calls:usize, fail:bool }
#[derive(Clone,Default)]
struct Fake(Rc<RefCell<State>>);
impl SecureVault for Fake {
 fn read(&mut self,key:&CredentialKey)->Result<Option<Secret>> {let mut state=self.0.borrow_mut();state.calls+=1;if state.fail{return Err(Error::VaultUnavailable);}state.data.get(key).map(|b|Secret::new(b.clone())).transpose()}
 fn write(&mut self,key:&CredentialKey,token:&Secret)->Result<()> {let mut state=self.0.borrow_mut();state.calls+=1;if state.fail{return Err(Error::VaultUnavailable);}state.data.insert(key.clone(),token.bytes().to_vec());Ok(())}
 fn delete(&mut self,key:&CredentialKey)->Result<()> {let mut state=self.0.borrow_mut();state.calls+=1;if state.fail{return Err(Error::VaultUnavailable);}state.data.remove(key);Ok(())}
}
fn session(fake:&Fake,env:CloudEnv,owner:&str,device:&str)->SessionVault<Fake> {SessionVault::new(Profile::ConnectedPreview,WorkspaceKind::Online,scope(env,owner,device),||Ok(fake.clone())).unwrap()}
fn token(value:&str)->Secret {Secret::new(value.as_bytes().to_vec()).unwrap()}
#[test]fn classic_identity_matches_original_contract(){let p=identity(Profile::Classic).unwrap();assert_eq!(p.app_id,"com.chs2147.workjourneyboard");assert_eq!(p.config_directory,"WorkJourneyBoard");assert_eq!(p.release_repository,Some("chs2147/work-journey-board"));}
#[test]fn preview_identity_is_distinct_and_has_no_release_feed(){let a=identity(Profile::Classic).unwrap();let b=identity(Profile::ConnectedPreview).unwrap();assert_ne!(a.app_id,b.app_id);assert_ne!(a.product_name,b.product_name);assert_ne!(a.config_directory,b.config_directory);assert_eq!(b.release_repository,None);assert!(updater_repository(Profile::ConnectedPreview).is_err());}
#[test]fn profile_keys_do_not_depend_on_ambient_environment(){assert_eq!(Profile::Classic.key(),"local-classic");assert_eq!(Profile::ConnectedPreview.key(),"connected-preview");}
#[test]fn classic_layout_does_not_require_cloud_scope(){let p=layout(Profile::Classic,synthetic_base(),None).unwrap();assert_eq!(p.settings,synthetic_base().join("WorkJourneyBoard").join("config.json"));assert!(p.registry.is_none());assert!(p.online_cache.is_none());assert_eq!(p.updates,Some(synthetic_base().join("com.chs2147.workjourneyboard").join("updates")));}
#[test]fn preview_config_and_runtime_are_disjoint_from_classic(){let base=synthetic_base();let a=layout(Profile::Classic,base,None).unwrap();let b=layout(Profile::ConnectedPreview,base,Some(target(CloudEnv::Development))).unwrap();for left in [&a.config_root,&a.native_root]{for right in [&b.config_root,&b.native_root]{assert!(!left.starts_with(right)&&!right.starts_with(left));}}assert_ne!(a.instance_namespace,b.instance_namespace);assert!(b.updates.is_none());}
#[test]fn preview_dev_and_prod_registry_and_cache_are_disjoint(){let a=layout(Profile::ConnectedPreview,synthetic_base(),Some(target(CloudEnv::Development))).unwrap();let b=layout(Profile::ConnectedPreview,synthetic_base(),Some(target(CloudEnv::Production))).unwrap();assert_ne!(a.project_root,b.project_root);assert_ne!(a.registry,b.registry);assert_ne!(a.online_cache,b.online_cache);assert_eq!(a.settings,b.settings);}
#[test]fn preview_cannot_fallback_to_ambient_or_missing_target(){assert!(layout(Profile::ConnectedPreview,synthetic_base(),None).is_err());assert!(layout(Profile::Classic,synthetic_base(),Some(target(CloudEnv::Development))).is_err());}
#[test]fn swapped_project_refs_and_unknown_refs_are_rejected(){assert_eq!(CloudTarget::new(CloudEnv::Development,"hutqsfftioxtredcjhsy"),Err(Error::CloudTargetMismatch));assert_eq!(CloudTarget::new(CloudEnv::Production,"vsphftnmfzfoufasjttd"),Err(Error::CloudTargetMismatch));assert!(CloudTarget::new(CloudEnv::Development,"").is_err());}
#[test]fn relative_and_parent_paths_are_rejected(){assert!(layout(Profile::Classic,Path::new("relative"),None).is_err());assert!(layout(Profile::Classic,Path::new("/synthetic/../classic"),None).is_err());}
#[test]fn classic_never_constructs_or_contacts_os_vault(){let called=RefCell::new(false);let result=SessionVault::<Fake>::new(Profile::Classic,WorkspaceKind::OfflineOnly,scope(CloudEnv::Development,OWNER_A,DEVICE_A),||{*called.borrow_mut()=true;panic!("must not initialize vault")});assert!(matches!(result,Err(Error::LocalModeHasNoVault)));assert!(!*called.borrow());}
#[test]fn classic_online_flag_does_not_enable_cloud_vault(){assert!(matches!(SessionVault::<Fake>::new(Profile::Classic,WorkspaceKind::Online,scope(CloudEnv::Development,OWNER_A,DEVICE_A),||panic!("must not initialize")),Err(Error::LocalModeHasNoVault)));}
#[test]fn preview_offline_workspace_never_constructs_os_vault(){assert!(matches!(SessionVault::<Fake>::new(Profile::ConnectedPreview,WorkspaceKind::OfflineOnly,scope(CloudEnv::Development,OWNER_A,DEVICE_A),||panic!("must not initialize")),Err(Error::LocalModeHasNoVault)));}
#[test]fn invalid_owner_or_device_ids_do_not_become_credential_names(){for value in ["", "../owner", "abc:owner", "11111111-1111-4111-8111-11111111111Z", "11111111-1111-4111-8111-111111111111\0"]{assert!(AccountScope::new(target(CloudEnv::Development),value,DEVICE_A).is_err());assert!(AccountScope::new(target(CloudEnv::Development),OWNER_A,value).is_err());}}
#[test]fn store_read_rotate_and_delete_use_one_exact_scope(){let fake=Fake::default();let mut s=session(&fake,CloudEnv::Development,OWNER_A,DEVICE_A);assert!(s.read_refresh_token().unwrap().is_none());s.write_refresh_token(&token("synthetic-first")).unwrap();assert_eq!(s.read_refresh_token().unwrap().unwrap().bytes(),b"synthetic-first");s.write_refresh_token(&token("synthetic-rotated")).unwrap();assert_eq!(s.read_refresh_token().unwrap().unwrap().bytes(),b"synthetic-rotated");s.logout().unwrap();assert!(s.read_refresh_token().unwrap().is_none());}
#[test]fn account_change_cannot_read_or_overwrite_previous_account(){let fake=Fake::default();let mut a=session(&fake,CloudEnv::Development,OWNER_A,DEVICE_A);let mut b=session(&fake,CloudEnv::Development,OWNER_B,DEVICE_A);a.write_refresh_token(&token("synthetic-A")).unwrap();assert!(b.read_refresh_token().unwrap().is_none());b.write_refresh_token(&token("synthetic-B")).unwrap();assert_eq!(a.read_refresh_token().unwrap().unwrap().bytes(),b"synthetic-A");assert_ne!(a.key(),b.key());}
#[test]fn dev_credentials_are_never_reused_by_production(){let fake=Fake::default();let mut a=session(&fake,CloudEnv::Development,OWNER_A,DEVICE_A);let mut b=session(&fake,CloudEnv::Production,OWNER_A,DEVICE_A);a.write_refresh_token(&token("synthetic-dev")).unwrap();assert!(b.read_refresh_token().unwrap().is_none());assert_ne!(a.key(),b.key());}
#[test]fn device_credentials_are_separate(){let fake=Fake::default();let mut a=session(&fake,CloudEnv::Development,OWNER_A,DEVICE_A);let mut b=session(&fake,CloudEnv::Development,OWNER_A,DEVICE_B);a.write_refresh_token(&token("synthetic-device-a")).unwrap();assert!(b.read_refresh_token().unwrap().is_none());assert_ne!(a.key(),b.key());}
#[test]fn logout_deletes_only_selected_key(){let fake=Fake::default();let mut a=session(&fake,CloudEnv::Development,OWNER_A,DEVICE_A);let mut b=session(&fake,CloudEnv::Development,OWNER_B,DEVICE_A);let mut prod=session(&fake,CloudEnv::Production,OWNER_A,DEVICE_A);for (s,value) in [(&mut a,"synthetic-A"),(&mut b,"synthetic-B"),(&mut prod,"synthetic-prod")]{s.write_refresh_token(&token(value)).unwrap();}a.logout().unwrap();assert!(a.read_refresh_token().unwrap().is_none());assert!(b.read_refresh_token().unwrap().is_some());assert!(prod.read_refresh_token().unwrap().is_some());assert_eq!(fake.0.borrow().data.len(),2);}
#[test]fn locked_vault_is_an_error_not_a_missing_token(){let fake=Fake::default();let mut a=session(&fake,CloudEnv::Development,OWNER_A,DEVICE_A);fake.0.borrow_mut().fail=true;assert!(matches!(a.read_refresh_token(),Err(Error::VaultUnavailable)));assert_eq!(a.write_refresh_token(&token("synthetic")),Err(Error::VaultUnavailable));assert_eq!(a.logout(),Err(Error::VaultUnavailable));}
#[test]fn factory_failure_propagates_without_fallback(){assert!(matches!(SessionVault::<Fake>::new(Profile::ConnectedPreview,WorkspaceKind::Online,scope(CloudEnv::Development,OWNER_A,DEVICE_A),||Err(Error::VaultUnavailable)),Err(Error::VaultUnavailable)));}
#[test]fn key_contains_no_token_and_uses_preview_service(){let fake=Fake::default();let a=session(&fake,CloudEnv::Development,OWNER_A,DEVICE_A);assert_eq!(a.key().service(),"com.chs2147.workjourneyboard.connected.preview.auth.v1");assert!(a.key().account().starts_with("development:vsphftnmfzfoufasjttd:"));assert!(!format!("{:?}",a.key()).contains("synthetic-token"));}
#[test]fn debug_redacts_secret_content(){let s=token("synthetic-sensitive-refresh");assert_eq!(format!("{s:?}"),"Secret([REDACTED])");assert!(!format!("{s:?}").contains("sensitive"));}
#[test]fn malformed_and_oversized_secrets_are_rejected(){for bytes in [vec![],vec![0xff],vec![b'x';MAX_SECRET_BYTES+1],b"line\r\nheader".to_vec(),b"nul\0value".to_vec()]{assert!(matches!(Secret::new(bytes),Err(Error::InvalidSecret)));}assert!(Secret::new(vec![b'x';MAX_SECRET_BYTES]).is_ok());}
#[test]fn error_output_is_fixed_and_contains_no_upstream_payload(){assert_eq!(Error::VaultUnavailable.to_string(),"VaultUnavailable");assert_eq!(format!("{:?}",Error::CloudTargetMismatch),"CloudTargetMismatch");}
#[cfg(not(any(target_os="windows",target_os="macos")))]
#[test]fn unsupported_host_does_not_select_a_plaintext_store(){assert!(matches!(crate::system_vault::SystemVault::new(),Err(Error::UnsupportedPlatform)));}
struct Temp(PathBuf);
impl Temp { fn new()->Self {static NEXT:AtomicUsize=AtomicUsize::new(0);let path=std::env::temp_dir().join(format!("wjb-native-{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::SeqCst)));std::fs::create_dir(&path).unwrap();Self(std::fs::canonicalize(path).unwrap())} }
impl Drop for Temp {fn drop(&mut self){std::fs::remove_dir_all(&self.0).unwrap();}}
#[test]fn existing_roots_do_not_overlap_original(){let t=Temp::new();let original=t.0.join("original");let preview=t.0.join("preview");std::fs::create_dir(&original).unwrap();std::fs::create_dir(&preview).unwrap();assert_eq!(validate_existing_root(&preview,&[original.clone()]),Ok(()));assert_eq!(validate_existing_root(&original,&[original.clone()]),Err(Error::PathOverlap));assert_eq!(validate_existing_root(&t.0,&[original]),Err(Error::PathOverlap));}
#[test]fn original_child_cannot_be_used_as_preview_state(){let t=Temp::new();let original=t.0.join("original");let child=original.join("preview");std::fs::create_dir_all(&child).unwrap();assert_eq!(validate_existing_root(&child,&[original]),Err(Error::PathOverlap));}
#[test]fn protected_roots_are_required_and_must_exist(){let t=Temp::new();assert_eq!(validate_existing_root(&t.0,&[]),Err(Error::InvalidPath));assert_eq!(validate_existing_root(&t.0,&[t.0.join("missing")]),Err(Error::InvalidPath));}
#[test]fn files_cannot_be_treated_as_profile_directories(){let t=Temp::new();let file=t.0.join("file");std::fs::write(&file,"synthetic").unwrap();assert_eq!(validate_existing_root(&file,&[t.0.clone()]),Err(Error::InvalidPath));}
#[cfg(unix)]
#[test]fn symlink_alias_is_rejected(){let t=Temp::new();let original=t.0.join("original");let alias=t.0.join("alias");std::fs::create_dir(&original).unwrap();std::os::unix::fs::symlink(&original,&alias).unwrap();assert_eq!(validate_existing_root(&alias,&[original]),Err(Error::PathAlias));}
#[test]fn validation_never_changes_original_config_or_db(){let t=Temp::new();let original=t.0.join("classic");let preview=t.0.join("preview");std::fs::create_dir(&original).unwrap();std::fs::create_dir(&preview).unwrap();for file in ["config.json","source.db"]{std::fs::write(original.join(file),"unchanged synthetic bytes").unwrap();}let before:Vec<_>=std::fs::read_dir(&original).unwrap().map(|e|e.unwrap().file_name()).collect();validate_existing_root(&preview,&[original.clone()]).unwrap();for file in ["config.json","source.db"]{assert_eq!(std::fs::read_to_string(original.join(file)).unwrap(),"unchanged synthetic bytes");}assert_eq!(std::fs::read_dir(&original).unwrap().count(),before.len());}
